import { createHash } from "crypto";
import { OrderEventKind } from "../domain/order";

const KIND_CODE: Record<OrderEventKind, string> = {
  PAID: "paid",
  SHIPPED: "ship",
  DELIVERED: "dlvd",
};

/**
 * 알림 메시지 키 — `<논리 키 해시 12자>.<네임스페이스>.<이벤트>.<업무 식별자>`.
 * 소비 측은 이 키로 이미 처리한 메시지를 걸러낸다(재전달 대비), 같은 알림은 늘 같은 키다.
 *
 * 앞머리를 해시로 두는 이유: mqpub 은 한 배치 안에서 키의 앞 16바이트가 같은 메시지를
 * 중복으로 보고 첫 것만 남긴다(오류 없음). 논리 키를 그대로 쓰면 같은 날 같은 종류의
 * 이벤트끼리 앞머리가 같아 조용히 버려진다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  const digest = createHash("sha1").update(logical).digest("hex").slice(0, 12);
  return `${digest}.${logical}`;
}

